Split `src/oop-pipeline.ts` (777L: 9 interfaces + 1 class + 1 factory = **11 public symbols**) into an 8-file module dir `src/oop-pipeline/`, plus a 1-line shim at the original path.

**File layout (8 files in the dir + 1 shim):**

```
src/oop-pipeline.ts              # shim: 1 line
src/oop-pipeline/
├── types.ts                     # 9 interfaces
├── token-utils.ts               # pure token helpers
├── extract.ts                   # pure extract* functions (explicit args)
├── helpers.ts                   # pure misc helpers (explicit args)
├── gather-reference-images.ts   # db-dependent fn (explicit db param)
├── oop-pipeline.ts              # class: stateful traversal + 3 generate*
├── factory.ts                   # createOopPipeline
└── index.ts                     # barrel: re-exports all 11 symbols
```

**1. `types.ts` — the 9 interfaces:**

```ts
export interface Token { kind: string; value: string; start: number; end: number; }
export interface StyleRule { property: string; value: string; important?: boolean; }
export interface StyleNode { id: string; selector: string; rules: StyleRule[]; children: StyleNode[]; }
export interface LocationNode { id: string; path: string; line: number; children: LocationNode[]; }
export interface ReferenceImage { path: string; hash: string; width: number; height: number; }
export interface Db { getImage(path: string): Promise<ReferenceImage | undefined>; }
export interface StyleHierarchyOptions { maxDepth?: number; includeTokens?: boolean; }
export interface LocationHierarchyOptions { baseDir?: string; followSymlinks?: boolean; }
export interface GenerateReportOptions { format: 'json' | 'markdown'; includeImages?: boolean; }
```

**2. `token-utils.ts` — pure token helpers, no class state:**

```ts
import { Token } from './types';

export function tokenize(source: string): Token[] { /* ... */ }
export function isToken(value: unknown): value is Token {
  return typeof value === 'object' && value !== null
    && 'kind' in value && 'start' in value && 'end' in value;
}
export function tokenAt(tokens: Token[], offset: number): Token | undefined {
  return tokens.find(t => offset >= t.start && offset < t.end);
}
```

**3. `extract.ts` — pure `extract*` functions converted to explicit args** (previously private methods reading `this.source`):

```ts
import { ReferenceImage, Token } from './types';
import { tokenize } from './token-utils';

export function extractImports(source: string): Token[] {
  return tokenize(source).filter(t => t.kind === 'import');
}
export function extractSelectors(source: string): string[] {
  return tokenize(source).filter(t => t.kind === 'selector').map(t => t.value);
}
export function extractReferences(source: string): ReferenceImage[] {
  return tokenize(source)
    .filter(t => t.kind === 'image-ref')
    .map(t => ({ path: t.value, hash: '', width: 0, height: 0 }));
}
```

**4. `helpers.ts` — other pure helpers, explicit args:**

```ts
export function sortByPosition<T extends { start: number }>(items: T[]): T[] {
  return [...items].sort((a, b) => a.start - b.start);
}
export function pathKey(path: string): string {
  return path.replace(/\\/g, '/').replace(/\/+/g, '/');
}
export function dedupe<T>(items: T[]): T[] { return [...new Set(items)]; }
```

**5. `gather-reference-images.ts` — db-dependent fn takes explicit `db` param** (no module-level singleton, no class field):

```ts
import { Db, ReferenceImage } from './types';

export async function gatherReferenceImages(refs: ReferenceImage[], db: Db): Promise<ReferenceImage[]> {
  const out: ReferenceImage[] = [];
  for (const ref of refs) {
    const meta = await db.getImage(ref.path);
    out.push(meta ? { ...ref, ...meta } : ref);
  }
  return out;
}
```

**6. `oop-pipeline.ts` — the class keeps ONLY stateful traversal + 3 public `generate*` methods:**

```ts
import {
  Db, GenerateReportOptions, LocationHierarchyOptions, LocationNode,
  ReferenceImage, StyleHierarchyOptions, StyleNode, Token,
} from './types';
import { tokenize } from './token-utils';
import { extractReferences } from './extract';
import { gatherReferenceImages } from './gather-reference-images';

export class OopPipeline {
  private readonly source: string;
  private readonly tokens: Token[];                      // stateful: tokenized once
  private readonly styleCache = new Map<string, StyleNode>();
  private readonly locCache = new Map<string, LocationNode>();

  constructor(source: string) {
    this.source = source;
    this.tokens = tokenize(source);                      // pure helper, explicit arg
  }

  /** Stateful traversal: memoized walk over this.tokens. */
  buildStyleHierarchy(options: StyleHierarchyOptions = {}): StyleNode {
    const key = `${this.tokens.length}:${options.maxDepth ?? -1}`;
    const hit = this.styleCache.get(key);
    if (hit) return hit;
    const root: StyleNode = { id: 'root', selector: '', rules: [], children: [] };
    // ... depth-limited walk over this.tokens, populating root ...
    this.styleCache.set(key, root);
    return root;
  }

  /** Stateful traversal: memoized walk, keeps baseDir state. */
  buildLocationHierarchy(options: LocationHierarchyOptions = {}): LocationNode {
    const key = `${options.baseDir ?? ''}:${options.followSymlinks ?? false}`;
    const hit = this.locCache.get(key);
    if (hit) return hit;
    const root: LocationNode = { id: 'root', path: '', line: 0, children: [] };
    // ... walk using this.source, populating root ...
    this.locCache.set(key, root);
    return root;
  }

  generateStyleHierarchy(options: StyleHierarchyOptions = {}): StyleNode {
    return this.buildStyleHierarchy(options);
  }
  generateLocationHierarchy(options: LocationHierarchyOptions = {}): LocationNode {
    return this.buildLocationHierarchy(options);
  }
  async generateReport(options: GenerateReportOptions, db: Db): Promise<string> {
    const refs: ReferenceImage[] = extractReferences(this.source);
    const resolved = options.includeImages ? await gatherReferenceImages(refs, db) : refs;
    return options.format === 'json' ? JSON.stringify(resolved) : resolved.map(r => r.path).join('\n');
  }
}
```

**7. `factory.ts`:**

```ts
import { OopPipeline } from './oop-pipeline';
export function createOopPipeline(source: string): OopPipeline {
  return new OopPipeline(source);
}
```

**8. `index.ts` — barrel must re-export ALL 11 symbols** (9 interfaces + class + factory). There is no parent barrel doing `export *`, so every name is public and must flow through here — omitting one silently shrinks the public API:

```ts
export * from './types';                    // 9 interfaces
export * from './token-utils';              // tokenize, isToken, tokenAt
export * from './extract';                  // extractImports, extractSelectors, extractReferences
export * from './helpers';                  // sortByPosition, pathKey, dedupe
export * from './gather-reference-images';  // gatherReferenceImages
export * from './oop-pipeline';             // OopPipeline
export * from './factory';                  // createOopPipeline
```

**9. `src/oop-pipeline.ts` — 1-line shim at the original path** (file and dir coexist; `./oop-pipeline` resolves to the dir's `index.ts`):

```ts
export * from './oop-pipeline';
```

**`verify.sh` — parity against `git show HEAD~1`, never the working tree** (the working tree may have uncommitted edits that would mask missing symbols):

```bash
#!/usr/bin/env bash
set -euo pipefail
# Expected surface = committed pre-split file (HEAD~1), NOT working tree.
git show HEAD~1:src/oop-pipeline.ts \
  | grep -oE '^export (declare )?(interface|class|function|const|type) [A-Za-z0-9_]+' \
  | awk '{print $NF}' | sort -u > /tmp/expected.txt
# Actual surface = all exported decls in the new module dir.
grep -rhoE '^export (interface|class|function|const|type) [A-Za-z0-9_]+' src/oop-pipeline/ \
  | awk '{print $NF}' | sort -u > /tmp/actual.txt
diff -u /tmp/expected.txt /tmp/actual.txt        # must be empty
test "$(wc -l < /tmp/actual.txt)" -eq 11         # exactly 11 symbols
# Ambiguity guard: names exported by >1 module are silently dropped by `export *`.
comm -12 /tmp/actual.txt <(grep -rhoE '^export (interface|class|function|const|type) [A-Za-z0-9_]+' src/oop-pipeline/ | awk '{print $NF}' | sort | uniq -d) | grep -q . && exit 1
npx tsc --noEmit                                 # typecheck
node -e "import('./src/oop-pipeline.ts').then(m => {          // shim smoke test
  const expect = ['OopPipeline','createOopPipeline','Token','StyleNode','LocationNode',
    'ReferenceImage','StyleRule','Db','StyleHierarchyOptions','LocationHierarchyOptions','GenerateReportOptions'];
  const missing = expect.filter(k => !(k in m));
  if (missing.length) { console.error('shim missing:', missing); process.exit(1); }
  console.log('shim surface OK'); })"
```
